from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]; out=root/'public/deliverables';out.mkdir(exist_ok=True)
data=json.loads((root/'data/model-results.json').read_text());styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitleCC',fontName='Helvetica',fontSize=25,leading=29,textColor=colors.HexColor('#193d30'),spaceAfter=14))
styles.add(ParagraphStyle(name='HeadCC',fontName='Helvetica-Bold',fontSize=11,leading=14,textColor=colors.HexColor('#193d30'),spaceBefore=12,spaceAfter=6))
styles.add(ParagraphStyle(name='BodyCC',fontName='Helvetica',fontSize=9.2,leading=13,spaceAfter=7,textColor=colors.HexColor('#34483b')))
styles.add(ParagraphStyle(name='SmallCC',fontName='Helvetica',fontSize=7.6,leading=10,textColor=colors.HexColor('#68766c'),spaceAfter=5))
def P(s,sty='BodyCC'):return Paragraph(s,styles[sty])
def footer(c,d):
 c.setStrokeColor(colors.HexColor('#cbd7ca'));c.line(44,39,568,39);c.setFont('Helvetica',8);c.setFillColor(colors.HexColor('#68766c'));c.drawString(44,25,'COMPUTE COMMONS / PS3 / 05 OCT 2026');c.drawRightString(568,25,str(d.page))
def doc(name,story):SimpleDocTemplate(str(out/name),pagesize=(612,792),leftMargin=44,rightMargin=44,topMargin=42,bottomMargin=52).build(story,onFirstPage=footer,onLaterPages=footer)
s=[P('University AI infrastructure<br/>Investment memorandum','TitleCC'),P('DECISION REQUEST / INITIAL CONCEPT / CONSTANT USD ASSUMPTIONS','SmallCC'),P('Recommendation','HeadCC'),P('Defer an irreversible 25 MW construction commitment. Procure a cancellable, benchmarked lease pilot to measure demand. Preserve a conditional 6.25 MW facility option only after signed member commitments and binding grid terms. Massachusetts is an illustrative domestic candidate for an assumed US university consortium, not a proven global optimum.'),P('Need and evidence','HeadCC'),P('The assignment provides no signed long-term member commitments and no confirmed grid price or energization date. The 20 MW IT baseline, PUE 1.25 and full-year operation imply 25 MW and 219 GWh. An illustrative 14,000 GPU-equivalent fleet at 65% utilization, 99% availability and 90% job efficiency provides 71.0 million productive GPU-hours annually. This is modeled demand, not a survey or customer contract.'),P('Three countries, with limits','HeadCC'),P('The US EIA reports approximately 4,300 TWh of electricity generation in 2024 [S4]. China reports 10,086.88 TWh [S2], while Singapore reports approximately 60 TWh [S3]. National generation does not establish spare grid capacity. Singapore reports a 94% natural-gas fuel share in 2024 [S3]. The comparable World Bank renewable series returned data for 2015 but null for the queried 2022 period [S5]. It remains explicitly historical.'),P('Ten-year comparison','HeadCC')]
rows=[['Case / option','Before open\n$ million','Annual opex\n$ million','$/productive\nGPU-hour','Capital risk\n$ million']]
for k,label in [('base','Base'),('delay','Delay'),('half','Half use')]:
 for r in data['cases'][k]:rows.append([label+' / '+{'Build & own':'Build','Lease capacity':'Lease','Phased hybrid':'Hybrid'}[r['strategy']],f"{r['preopening']/1e6:,.1f}",f"{r['annualOpex']/1e6:,.1f}",f"{r['costPerHour']:.2f}",f"{r['risk']/1e6:,.1f}"])
t=Table(rows,colWidths=[142,91,95,101,95],repeatRows=1);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#193d30')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),8),('LEADING',(0,0),(-1,-1),11),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.HexColor('#eef2e8'),colors.white]),('ALIGN',(1,1),(-1,-1),'RIGHT'),('VALIGN',(0,0),(-1,-1),'MIDDLE')]))
s +=[t,Spacer(1,8),P('Calculated from labeled illustrative inputs, not market quotes. Annual opex is the first fully operating year. Delay means one extra year of leased bridge compute for owned options. All options serve equivalent demand. Capital risk is an assumed loss exposure, not a forecast loss probability.','SmallCC'),PageBreak(),P('What would justify ownership?','TitleCC'),P('Model and financing boundaries','HeadCC'),P('The model separates facility ($250m), grid allowance ($20m) and IT fleet ($560m) at full scale. Facility cost is $10m per total MW and IT fleet cost is $40,000 per equivalent GPU. These inputs include conceptual power/cooling and non-GPU IT allocation, respectively. Electricity is $0.09/kWh and leased allocation is $3/GPU-hour. None is a verified quote.'),P('The 10-calendar-year window begins at planned opening. Fleet replacements occur after four and eight operating years. Real discount rate is 8%, no tax or inflation is modeled, and residual value is zero. Debt funds 50% of facility/grid at 7% real interest with ten equal principal payments. Project unit cost excludes financing flows to avoid double-counting capital cost. Equity cash requirements display principal and interest separately.'),P('Pre-opening cash is a gross funding requirement, including a three-month lease prepayment credited against later rent. Delay adds bridge operating costs, holding cost and interest. Capital risk assumes 80% loss on facility/grid, 70% on fleet, and three months of lease commitments. Idle energy remains 40% of full load before the variable utilization component. Changes to these assumptions may change the decision.'),P('Engineering and risk allocation','HeadCC'),P('For a conditional 6.25 MW phase, propose two independent 8 MVA transformer paths, N+1 UPS/cooling and five 2 MW generators with four required. At full phase load, a 48-hour outage requires 300 MWh. Assumed fuel use of 0.25 L/kWh plus 20% reserve implies 90,000 L. Verify derating, transfer tests, tank permits, fuel logistics and cooling continuity. No renewable or battery energy is credited as firm 48-hour supply.'),P('A member nonprofit would own the shell and electrical/cooling assets and contract construction and qualified operations. Demand shortfall and member withdrawal require minimum-use commitments and reserves. Development equity carries early permitting loss. Construction debt requires permits, firm grid dates/costs, construction contingency and enforceable member contracts. Equipment finance requires delivery and acceptance tests, warranty and refresh terms.'),P('Findings most likely to reverse the recommendation','HeadCC'),P('<b>1. Demand:</b> Signed commitments plus measured job traces demonstrate sustained utilization high enough to overcome ownership costs. Require synchronized-cluster benchmarks, not just annual GPU-hours.<br/><b>2. Power:</b> A binding interconnection agreement fixes tariff, upgrade liability and date, with validated 48-hour resilience.<br/><b>3. Comparable bids:</b> Delivered hardware and cloud bids show a durable ownership advantage after storage, networking, support, replacement and exit costs.'),P('Governance and external effects','HeadCC'),P('Use published quotas, metered variable charges and one institution-one vote. Reserve teaching access for smaller institutions, reclaim unused slots and offer appeals. Assess water allocation, noise, emissions, permits and whether grid upgrades shift costs to other customers. Data residency and hardware availability remain separate country-specific diligence items.'),P('Source register','HeadCC')]
for id,publisher,url in [('S2','China NBS, 2024 communiqué','https://www.stats.gov.cn/english/PressRelease/202502/t20250228_1958822.html'),('S3','Singapore EMA, Energy Transformation','https://www.ema.gov.sg/resources/singapore-energy-statistics/chapter2'),('S4','US EIA, 2024 energy statistics','https://www.eia.gov/energyexplained/us-energy-facts/data-and-statistics.php'),('S5','World Bank, EG.ELC.RNEW.ZS','https://data.worldbank.org/indicator/EG.ELC.RNEW.ZS')]:s.append(P(f'[{id}] <link href="{url}" color="#31664c">{publisher}</link>. Accessed 2026-10-05. Full provenance in website Evidence.','SmallCC'))
doc('investment-memo.pdf',s)
a=[P('Software architecture','TitleCC'),P('A request from the browser to evidence and back','BodyCC')]
for title,text in [('1. Browser','Public pages request /api/data. A user signs in through the platform-owned ChatGPT flow, then explicitly registers for this application.'),('2. Sites backend','Every write checks the request origin. AI requires identity plus a users record. Refresh needs editor/admin. Saving assumptions and role changes need admin. Identity comes from the trusted Sites dispatcher, never from a user-entered ID.'),('3. Cloudflare D1','Sources, metrics, countries, designs, claims and registrations persist in eight tables including audit events and rate limits. Prepared statements bind values. Schema migrations run before deployment. An idempotent seed batch inserts the initial evidence separately.'),('4. Deterministic model','The same calculation functions power the browser and adviser tools. They calculate site power, productive GPU-hours, ten-year costs and three stress cases. The language model explains these results instead of inventing arithmetic.'),('5. Approved external API','An editor can refresh a fixed World Bank endpoint. The backend validates country, indicator, year, range and numeric values before committing a batch. Any failure preserves the last valid observations. Each record retains its retrieval date.'),('6. OpenAI Responses API','After registration and hourly rate checks, the server retrieves relevant D1 evidence and calls OpenAI with controlled read/calculation tools. At most three model turns per question. Server credentials never reach the browser. Sources are data, not instructions.'),('7. Cited response','The server validates JSON structure and source IDs against retrieved records, then returns the answer, assumptions, uncertainty, links and token count. Invalid citations fail closed. Source-ID validity does not by itself prove that a source entails the claim.'),('Operational boundary','The native platform provides hosted identity. Local preview uses a loopback-only mock user. Live AI answers and injection resistance require an approved hosted key and real testing. Initial publication is private, so anonymous hosted access remains unverified until the owner authorizes a public audience.')]:a.extend([P(title,'HeadCC'),P(text)])
doc('architecture.pdf',a)
print('Created investment-memo.pdf and architecture.pdf')
